<?php
declare(strict_types=1);
$sql=[
"ALTER TABLE svc_services ADD COLUMN current_price_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL",
"UPDATE svc_services s JOIN svc_periods p ON p.id=s.current_period_id SET s.current_price_id=p.price_id",
"CREATE TABLE svc_transfers (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,from_customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,to_customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,sender_user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,sender_session_reference CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,sender_identity_version INT UNSIGNED NOT NULL,service_version BIGINT UNSIGNED NOT NULL,token_hmac CHAR(64) CHARACTER SET ascii NOT NULL,policy_hmac CHAR(64) CHARACTER SET ascii NOT NULL,expires_at DATETIME(6) NOT NULL,status VARCHAR(16) CHARACTER SET ascii NOT NULL DEFAULT 'PENDING',recipient_user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),completed_at DATETIME(6) NULL,KEY ix_svc_transfer(service_id,status,expires_at),FOREIGN KEY(service_id) REFERENCES svc_services(id),CHECK(from_customer_id<>to_customer_id),CHECK(status IN ('PENDING','COMPLETED','CANCELLED'))) ENGINE=InnoDB",
"CREATE TRIGGER svc_transfer_binding BEFORE UPDATE ON svc_transfers FOR EACH ROW BEGIN IF OLD.service_id<>NEW.service_id OR OLD.from_customer_id<>NEW.from_customer_id OR OLD.to_customer_id<>NEW.to_customer_id OR OLD.sender_user_id<>NEW.sender_user_id OR OLD.sender_session_reference<>NEW.sender_session_reference OR OLD.sender_identity_version<>NEW.sender_identity_version OR OLD.service_version<>NEW.service_version OR OLD.token_hmac<>NEW.token_hmac OR OLD.policy_hmac<>NEW.policy_hmac OR OLD.expires_at<>NEW.expires_at OR (OLD.status<>'PENDING' AND (NEW.status<>OLD.status OR NOT(NEW.recipient_user_id <=> OLD.recipient_user_id) OR NOT(NEW.completed_at <=> OLD.completed_at))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable transfer approval binding'; END IF; END",
];
$permissions=['services.approve','services.reconcile','services.policy','services.renew','services.wallet','services.cancel','services.suspend','services.unsuspend','services.terminate','services.transfer','services.transfer.accept','services.package','services.pools'];
foreach($permissions as $permission){$sql[]="INSERT INTO identity_permissions(code) VALUES ('$permission')";$sql[]="INSERT INTO identity_role_permissions(role_id,permission) SELECT id,'$permission' FROM identity_roles WHERE name='Super Admin'";}
foreach(['services.renew','services.wallet','services.cancel','services.transfer','services.transfer.accept','services.package'] as $permission){$sql[]="INSERT INTO identity_role_permissions(role_id,permission) SELECT id,'$permission' FROM identity_roles WHERE name='Müşteri Sahibi'";}
$sql[]='UPDATE identity_users SET identity_version=identity_version+1';$sql[]='UPDATE identity_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE revoked_at IS NULL';return $sql;
